// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public {
        c = SimpleWallet(new SimpleWallet());
    }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(amount > 0 && amount < 1e24);
        vm.assume(actor != address(0) && actor.code.length == 0);

        // owner of c is whoever deploys it; deploy from the fuzzed EOA
        vm.prank(actor);
        c = SimpleWallet(new SimpleWallet());

        // fund the actor and deposit via the payable fallback
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amount}("");
        assertTrue(ok);

        // owner withdraws everything
        vm.prank(actor);
        c.withdrawAll();

        // the whole deposit left the contract
        assertEq(address(c).balance, 0);
    }
}
